-- Nouvelles questions Histoire, Cinéma et Sport écrites pour un public français, relues à la main :
-- doublons, réponses fausses ou ambiguës, faits datés et anecdotes sans intérêt écartés.
INSERT INTO "Question" ("id", "sourceId", "questionEn", "questionFr", "answersEn", "answersFr", "correctIndex", "category", "difficulty", "createdAt") VALUES
    (gen_random_uuid()::text, 'gen-afd7d3cf3047f2aa', 'In which years did the violent period of the French Revolution known as the ''Terror'' take place?', 'Durant quelles années s''est déroulée la période particulièrement violente de la Révolution appelée la « Terreur » ?', '["1795-1796", "1793-1794", "1789-1790", "1799-1800"]'::jsonb, '["1795-1796", "1793-1794", "1789-1790", "1799-1800"]'::jsonb, 1, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-fc02b86a03251f11', 'What event, organized to solve the budget crisis, triggered the French Revolution?', 'Quel événement, organisé pour résoudre la crise budgétaire, a déclenché la Révolution française ?', '["The abolition of privileges", "The convocation of the Estates-General", "The storming of the Bastille", "The execution of the king"]'::jsonb, '["L''abolition des privilèges", "La convocation des états généraux", "La prise de la Bastille", "L''exécution du roi"]'::jsonb, 1, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-200566b402ab46e9', 'On which island was Napoleon Bonaparte born in 1769?', 'Sur quelle île est né Napoléon Bonaparte en 1769 ?', '["Sicily", "Elba", "Sardinia", "Corsica"]'::jsonb, '["La Sicile", "L''île d''Elbe", "La Sardaigne", "La Corse"]'::jsonb, 3, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-b76073bb7acd1e9b', 'To which country did Napoleon sell Louisiana in 1803?', 'À quel pays Napoléon a-t-il vendu la Louisiane en 1803 ?', '["Spain", "Canada", "Great Britain", "United States"]'::jsonb, '["L''Espagne", "Le Canada", "La Grande-Bretagne", "Les États-Unis"]'::jsonb, 3, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-1f6ad6ded12c43d6', 'Which of his brothers did Napoleon place on the throne of Spain?', 'Quel frère de Napoléon a été placé par ce dernier sur le trône d''Espagne ?', '["Lucien", "Louis", "Jérôme", "Joseph"]'::jsonb, '["Lucien", "Louis", "Jérôme", "Joseph"]'::jsonb, 3, 'History', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-58bec56c29276e28', 'Napoleon formally restored the independence of Poland by creating the Duchy of Warsaw.', 'Napoléon a formellement restauré l''indépendance de la Pologne en créant le duché de Varsovie.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-10dd731940186222', 'How many years did Napoleon spend at the military school of Brienne?', 'Combien d''années Napoléon a-t-il passées à l''école militaire de Brienne ?', '["8 years", "10 years", "2 years", "5 years"]'::jsonb, '["8 ans", "10 ans", "2 ans", "5 ans"]'::jsonb, 3, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-03faf4e66a128581', 'Due to the time difference, which country celebrated the end of World War II in Europe on May 9, 1945, instead of May 8?', 'En raison du décalage horaire, quel pays a célébré la fin de la guerre en Europe le 9 mai 1945 au lieu du 8 mai ?', '["China", "United States", "USSR", "United Kingdom"]'::jsonb, '["La Chine", "Les États-Unis", "L''URSS", "Le Royaume-Uni"]'::jsonb, 2, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-31b8d81146af6615', 'World War II ended simultaneously in Europe and the Asia-Pacific region in May 1945.', 'La Seconde Guerre mondiale s''est terminée le même jour en Europe et dans la région Asie-Pacifique en mai 1945.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-41935bf365f804b6', 'At the beginning of World War II, the USSR was initially associated with Germany in partitioning Europe before joining the Allies.', 'Au début de la Seconde Guerre mondiale, l''URSS était initialement associée à l''Allemagne pour partager l''Europe avant de rejoindre les Alliés.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-c562587e153c7978', 'Approximately how many combatants were mobilized globally during World War II?', 'Environ combien de combattants ont été mobilisés dans le monde pendant la Seconde Guerre mondiale ?', '["Around 50 million", "More than 100 million", "Around 10 million", "More than 500 million"]'::jsonb, '["Environ 50 millions", "Plus de 100 millions", "Environ 10 millions", "Plus de 500 millions"]'::jsonb, 1, 'History', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-83e9698142965f40', 'What embargo imposed by the United States in 1941 led Japan to authorize the attack on Pearl Harbor?', 'Quel embargo imposé par les États-Unis en 1941 a poussé le Japon à autoriser l''attaque de Pearl Harbor ?', '["Wheat", "Coal", "Oil", "Steel"]'::jsonb, '["Le blé", "Le charbon", "Le pétrole", "L''acier"]'::jsonb, 2, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-f9ffd668b7d79608', 'In which book, written in 1924, did Adolf Hitler express his expansionist ambitions?', 'Dans quel ouvrage, écrit en 1924, Adolf Hitler exprime-t-il ses ambitions expansionnistes ?', '["The Doctrine of Fascism", "Mein Kampf", "The Myth of the Twentieth Century", "The Capital"]'::jsonb, '["La Doctrine du fascisme", "Mein Kampf", "Le Mythe du vingtième siècle", "Le Capital"]'::jsonb, 1, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-cd97c5e359700604', 'Where in Africa did the Italian fascist regime attempt to establish a colonial empire during the march to World War II?', 'Où en Afrique le régime fasciste italien a-t-il tenté de se constituer un empire colonial durant la marche vers la Seconde Guerre mondiale ?', '["Egypt", "Congo", "Algeria", "Ethiopia"]'::jsonb, '["L''Égypte", "Le Congo", "L''Algérie", "L''Éthiopie"]'::jsonb, 3, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-dcd142e1384f7672', 'Which archduke was assassinated in Sarajevo in 1914, triggering the outbreak of World War I?', 'Quel archiduc a été assassiné à Sarajevo en 1914, déclenchant l''engrenage de la Première Guerre mondiale ?', '["Charles Albert", "Franz Ferdinand", "Rudolf", "William John"]'::jsonb, '["Charles-Albert", "François-Ferdinand", "Rodolphe", "Guillaume-Jean"]'::jsonb, 1, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-978e6fb1d302ce58', 'What nickname was given to Louis XIV at birth?', 'Quel surnom a été donné à Louis XIV à sa naissance ?', '["Désiré", "Dieudonné", "Jean-Baptiste", "Le-Grand"]'::jsonb, '["Désiré", "Dieudonné", "Jean-Baptiste", "Le-Grand"]'::jsonb, 1, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-80cb6db94010924e', 'Who directly succeeded Louis XIV on the French throne?', 'Qui a succédé directement à Louis XIV sur le trône de France ?', '["His son", "His grandson", "His brother", "His great-grandson"]'::jsonb, '["Son fils", "Son petit-fils", "Son frère", "Son arrière-petit-fils"]'::jsonb, 3, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-cebba16ccb85690a', 'The regency during Louis XIV''s youth was led by Marie de'' Medici.', 'La régence durant la minorité de Louis XIV a été assurée par Marie de Médicis.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-8c9242e0fe6d298a', 'In which royal château was Louis XIV born?', 'Dans quel château royal est né Louis XIV ?', '["Chambord", "Fontainebleau", "Versailles", "Saint-Germain-en-Laye"]'::jsonb, '["Chambord", "Fontainebleau", "Versailles", "Saint-Germain-en-Laye"]'::jsonb, 3, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-a7ac6fa3fc34e271', 'The French public holiday of August 15th originates from a vow to thank the Virgin Mary for the future birth of Louis XIV.', 'Le jour férié du 15 août en France trouve son origine dans un vœu pour remercier la Vierge de la future naissance de Louis XIV.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-3f6d6b9e638101e2', 'What was the name of Louis XIV''s younger brother, born two years after him?', 'Quel était le prénom du frère cadet de Louis XIV, né deux ans après lui ?', '["Gaston", "Charles", "Henri", "Philippe"]'::jsonb, '["Gaston", "Charles", "Henri", "Philippe"]'::jsonb, 3, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-636ea273a3ad9ec6', 'In which city was the French king Charles VII crowned thanks to Joan of Arc?', 'Dans quelle ville le roi Charles VII a-t-il été sacré grâce à Jeanne d''Arc ?', '["Rouen", "Orléans", "Reims", "Paris"]'::jsonb, '["Rouen", "Orléans", "Reims", "Paris"]'::jsonb, 2, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-6a7bf1d7efa8385d', 'Who conducted the heresy trial of Joan of Arc?', 'Qui a mené le procès en hérésie de Jeanne d''Arc ?', '["Jean de Luxembourg", "Henri V", "Charles VII", "Pierre Cauchon"]'::jsonb, '["Jean de Luxembourg", "Henri V", "Charles VII", "Pierre Cauchon"]'::jsonb, 3, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-fb46eba7191564be', 'Which French princess did King Henry V of England marry under the Treaty of Troyes?', 'Quelle princesse française le roi Henri V d''Angleterre a-t-il épousée selon le traité de Troyes ?', '["Catherine de Valois", "Marguerite d''Antioche", "Catherine d''Alexandrie", "Isabeau de Bavière"]'::jsonb, '["Catherine de Valois", "Marguerite d''Antioche", "Catherine d''Alexandrie", "Isabeau de Bavière"]'::jsonb, 0, 'History', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-c4a4d694cb4dcb15', 'Which royal figure was nicknamed the ''King of Bourges'' by his enemies during the Hundred Years'' War?', 'Quel personnage historique était surnommé le « roi de Bourges » par ses ennemis pendant la guerre de Cent Ans ?', '["Henri VI", "Jean de Bedford", "Charles VII", "Louis XI"]'::jsonb, '["Henri VI", "Jean de Bedford", "Charles VII", "Louis XI"]'::jsonb, 2, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-037599d20fc65e95', 'Following the Treaty of Troyes, who was the infant proclaimed King of both France and England?', 'À la suite du traité de Troyes, quel enfant est proclamé roi de France et d''Angleterre ?', '["Henri V", "Jean de Bedford", "Henri VI", "Charles VII"]'::jsonb, '["Henri V", "Jean de Bedford", "Henri VI", "Charles VII"]'::jsonb, 2, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-e5cc4ce2106977b6', 'Jeanne d''Arc was born in the village of Domrémy.', 'Jeanne d''Arc est née dans le village de Domrémy.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-e80bca72f189c92e', 'Which French region had been under English control for three centuries by the time of the double monarchy?', 'Quelle région française était sous contrôle anglais depuis trois siècles au moment de la double monarchie ?', '["Aquitaine", "Brittany", "Normandy", "Champagne"]'::jsonb, '["Aquitaine", "Bretagne", "Normandie", "Champagne"]'::jsonb, 0, 'History', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-2b1205afba0967f9', 'Historians have definitively confirmed the exact date of Jeanne d''Arc''s birth thanks to parish registers.', 'Les historiens ont pu confirmer avec certitude la date exacte de naissance de Jeanne d''Arc grâce aux registres paroissiaux.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-ca1bb051938d40dc', 'Which river is synonymous with the development of Ancient Egyptian civilization?', 'Quel fleuve est indissociable du développement de la civilisation de l''Égypte antique ?', '["The Indus", "The Nile", "The Tigris", "The Euphrates"]'::jsonb, '["L''Indus", "Le Nil", "Le Tigre", "L''Euphrate"]'::jsonb, 1, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-26ddb83de92a3a84', 'The Ancient Egyptian civilization ended when it was conquered by the Roman Empire.', 'La civilisation de l''Égypte antique a pris fin suite à sa conquête par l''Empire romain.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-4735719e1588607d', 'Which group formed the essential administrative backbone of the Egyptian royal power?', 'Quel corps constituait le pilier administratif essentiel du pouvoir royal égyptien ?', '["Scribes", "Merchants", "Soldiers", "Farmers"]'::jsonb, '["Les scribes", "Les marchands", "Les soldats", "Les paysans"]'::jsonb, 0, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-d9ab80ce0f44e9af', 'What major political event marked the birth of Ancient Egyptian civilization around 3150 BC?', 'Quel événement politique majeur marque la naissance de l''Égypte antique vers 3150 av. J.-C. ?', '["The conquest of the Nile Delta", "The unification of Upper and Lower Egypt", "The construction of the first pyramid", "The invention of the first alphabet"]'::jsonb, '["La conquête du delta du Nil", "L''unification de la Haute et de la Basse-Égypte", "La construction de la première pyramide", "L''invention du premier alphabet"]'::jsonb, 1, 'History', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-4dd276a16d362eb2', 'King Menes is traditionally considered the unifier of Upper and Lower Egypt.', 'Le roi Ménès est traditionnellement considéré comme celui qui a unifié la Haute et la Basse-Égypte.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-72cdb9d2f2028945', 'What type of ceramic glaze did the Nagada culture develop?', 'Quel type d''émail céramique la culture Nagada a-t-elle mis au point ?', '["Faience", "Porcelain", "Terracotta", "Stoneware"]'::jsonb, '["La faïence", "La porcelaine", "La terre cuite", "Le grès"]'::jsonb, 0, 'History', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-d996b431e43cfe28', 'Ancient Rome was founded on the banks of the Tiber River.', 'La Rome antique a été fondée sur les rives du fleuve Tibre.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-5152310f7f6e2278', 'In which year did the Western Roman Empire officially come to an end?', 'En quelle année l''Empire romain d''Occident a-t-il officiellement pris fin ?', '["476", "395", "753", "512"]'::jsonb, '["476", "395", "753", "512"]'::jsonb, 0, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-ec183a25ff9b2ff1', 'What was the name of the hereditary clan groups that formed the basis of early Roman society?', 'Comment appelait-on les groupes héréditaires ou « clans » qui formaient la base de la société romaine primitive ?', '["Pater", "Urbs", "Latium", "Gentes"]'::jsonb, '["Pater", "Urbs", "Latium", "Gentes"]'::jsonb, 3, 'History', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-529cd561255ba977', 'Which animal is said to have raised the twins Romulus and Remus in the Roman foundation myth?', 'Quel animal aurait élevé les jumeaux Romulus et Rémus dans le mythe de la fondation de Rome ?', '["A wolf", "A tigress", "A lioness", "A bear"]'::jsonb, '["Une louve", "Une tigresse", "Une lionne", "Une ourse"]'::jsonb, 0, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-81ae9d31317a57f1', 'Which ancient poet wrote the Aeneid, the epic poem about the Trojan hero Aeneas?', 'Quel poète antique a écrit l''Énéide, le poème épique sur le héros troyen Énée ?', '["Virgil", "Cicero", "Homer", "Ovid"]'::jsonb, '["Virgile", "Cicéron", "Homère", "Ovide"]'::jsonb, 0, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-a9244b52fb2a8545', 'What specific role was Rhea Silvia, mother of Romulus and Remus, forced to take?', 'Quel rôle particulier Rhea Silvia, la mère de Romulus et Rémus, a-t-elle été forcée de tenir ?', '["A queen", "A goddess", "A vestal", "A slave"]'::jsonb, '["Une reine", "Une déesse", "Une vestale", "Une esclave"]'::jsonb, 2, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-3c1e98e96366bf98', 'According to tradition, the city of Rome was founded in 753 BC.', 'Selon la tradition, la ville de Rome a été fondée en 753 av. J.-C.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-e462390814cf851e', 'In the legend of Rome''s foundation, Romulus and Remus founded the city together after ruling it in perfect harmony.', 'Dans la légende de la fondation de Rome, Romulus et Rémus ont fondé la ville ensemble après l''avoir dirigée en parfaite harmonie.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-aec2b08b871d1017', 'The Cold War is called ''cold'' because the USA and the USSR were in constant direct military combat against each other.', 'La guerre froide est qualifiée de « froide » car les États-Unis et l''URSS étaient en combat militaire direct permanent.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-7ed7d81b5dd7f053', 'What type of race, involving huge resources, characterized the Cold War between the two superpowers?', 'Quel type de course, mobilisant des ressources colossales, a caractérisé la guerre froide entre les deux superpuissances ?', '["Economic trade race", "Nuclear arms race", "Colonial expansion race", "Naval expansion race"]'::jsonb, '["Course aux échanges commerciaux", "Course aux armements nucléaires", "Course à l''expansion coloniale", "Course à l''expansion navale"]'::jsonb, 1, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-1962cd8d3984f2f7', 'True or False: Despite its name, the Cold War saw several violent open conflicts in Asia.', 'Vrai ou Faux : Malgré son nom, la guerre froide a connu plusieurs conflits armés violents en Asie.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-9d00053bf95c1801', 'Which political regime was founded by Charles de Gaulle?', 'Quel régime politique a été fondé par Charles de Gaulle ?', '["The Fifth Republic", "The Fourth Republic", "The Second Empire", "The Restoration"]'::jsonb, '["La Ve République", "La IVe République", "Le Second Empire", "La Restauration"]'::jsonb, 0, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-2e10cc2dc721a77e', 'From which city did Charles de Gaulle broadcast his famous appeal on June 18, 1940?', 'Depuis quelle ville Charles de Gaulle a-t-il lancé son célèbre appel du 18 juin 1940 ?', '["Paris", "London", "Bordeaux", "Algiers"]'::jsonb, '["Paris", "Londres", "Bordeaux", "Alger"]'::jsonb, 1, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-bbd2b433848ffde4', 'Charles de Gaulle died in Paris.', 'Charles de Gaulle est mort à Paris.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-23209a3481026469', 'Which event led to Charles de Gaulle''s resignation in 1969?', 'Quel événement a conduit à la démission de Charles de Gaulle en 1969 ?', '["A health crisis", "The failure of a referendum", "A motion of no confidence", "The loss of the legislative elections"]'::jsonb, '["Un problème de santé", "L''échec d''un référendum", "Une motion de censure", "La perte des élections législatives"]'::jsonb, 1, 'History', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-b57b8fb331c201a8', 'Charles de Gaulle is the president who initiated the French nuclear deterrent force.', 'Charles de Gaulle est le président qui a mis en place la force de dissuasion nucléaire française.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-35c4116b710f0ad2', 'During which conflict was Charles de Gaulle wounded and taken prisoner?', 'Lors de quel conflit Charles de Gaulle a-t-il été blessé et fait prisonnier ?', '["The Franco-Prussian War", "World War II", "World War I", "The Algerian War"]'::jsonb, '["La guerre franco-prussienne", "La Seconde Guerre mondiale", "La Première Guerre mondiale", "La guerre d''Algérie"]'::jsonb, 2, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-da61fe65d7d1eae2', 'In which French city was Charles de Gaulle born?', 'Dans quelle ville française Charles de Gaulle est-il né ?', '["Marseille", "Paris", "Lyon", "Lille"]'::jsonb, '["Marseille", "Paris", "Lyon", "Lille"]'::jsonb, 3, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-881958a5a07da4ec', 'What day of the year was Charles de Gaulle born?', 'Quel jour de l''année Charles de Gaulle est-il né ?', '["May 8", "June 18", "November 22", "July 14"]'::jsonb, '["Le 8 mai", "Le 18 juin", "Le 22 novembre", "Le 14 juillet"]'::jsonb, 2, 'History', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-3fb5f42c4671b516', 'In which city was the famous wall built in 1961?', 'Dans quelle ville le célèbre mur a-t-il été érigé en 1961 ?', '["Frankfurt", "Hamburg", "Berlin", "Munich"]'::jsonb, '["Francfort", "Hambourg", "Berlin", "Munich"]'::jsonb, 2, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-d460d9e2b0e2d83d', 'What did the East German government officially call the Berlin Wall?', 'Quel nom le gouvernement est-allemand donnait-il officiellement au mur de Berlin ?', '["Peace fence", "Unity barrier", "Anti-fascist protection rampart", "Socialist shield"]'::jsonb, '["Clôture de paix", "Barrière de l''unité", "Rempart antifasciste", "Bouclier socialiste"]'::jsonb, 2, 'History', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-99681b36b9c3a2b1', 'The Berlin Wall fell in 1989.', 'Le mur de Berlin est tombé en 1989.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'History', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-21112cd0326321dc', 'What was the total length of the Berlin Wall surrounding the western sector?', 'Quelle était la longueur totale du mur entourant le secteur ouest de Berlin ?', '["80 km", "155 km", "45 km", "210 km"]'::jsonb, '["80 km", "155 km", "45 km", "210 km"]'::jsonb, 1, 'History', 'hard', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-38fc9d492434ff37', 'The Soviet Union organized a blockade of Berlin in 1955.', 'L''Union soviétique a organisé un blocus de Berlin en 1955.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 1, 'History', 'medium', CURRENT_TIMESTAMP),
