    (gen_random_uuid()::text, 'gen-87bf48c040637102', 'Cristiano Ronaldo is the record holder for goals scored with his national team.', 'Cristiano Ronaldo détient le record de buts marqués avec sa sélection nationale.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Sports', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-364035d56e0d050d', 'Where does Cristiano Ronaldo''s famous nickname ''CR7'' come from?', 'D''où vient le célèbre surnom ''CR7'' de Cristiano Ronaldo ?', '["The number of goals in his first season", "His jersey number at Manchester United", "His favorite player''s number", "His birth date"]'::jsonb, '["Son nombre de buts lors de sa première saison", "Son numéro de maillot à Manchester United", "Le numéro de son joueur préféré", "Sa date de naissance"]'::jsonb, 1, 'Sports', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-231b875337d306db', 'What health problem did Cristiano Ronaldo face at the age of 15?', 'Quel problème de santé Cristiano Ronaldo a-t-il rencontré à l''âge de 15 ans ?', '["A severe knee injury", "A chronic lung infection", "A heart condition", "A broken leg"]'::jsonb, '["Une grave blessure au genou", "Une infection pulmonaire chronique", "Un problème cardiaque", "Une fracture de la jambe"]'::jsonb, 2, 'Sports', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-8c8c084cd378b44f', 'Cristiano Ronaldo was in a relationship with the Russian top model Irina Shayk.', 'Cristiano Ronaldo a été en couple avec le mannequin russe Irina Shayk.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Sports', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-3364dccefa8da974', 'In which club did a young Cristiano Ronaldo begin his football journey?', 'Dans quel club le jeune Cristiano Ronaldo a-t-il fait ses débuts ?', '["Sporting CP", "CD Nacional", "FC Andorinha", "Benfica Lisbonne"]'::jsonb, '["Sporting CP", "CD Nacional", "FC Andorinha", "Benfica Lisbonne"]'::jsonb, 2, 'Sports', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-82bade84ebe5d5b3', 'Which club did Cristiano Ronaldo join in 2003 for 15 million euros?', 'Quel club Cristiano Ronaldo a-t-il rejoint en 2003 pour 15 millions d''euros ?', '["Sporting CP", "Juventus Turin", "Real Madrid", "Manchester United"]'::jsonb, '["Sporting CP", "Juventus Turin", "Real Madrid", "Manchester United"]'::jsonb, 3, 'Sports', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-68ba2741e713bbfa', 'In which city were the 2024 Summer Olympics officially awarded to Paris?', 'Dans quelle ville les Jeux olympiques d''été 2024 ont-ils été officiellement attribués à Paris ?', '["Lima", "Lausanne", "Tokyo", "Los Angeles"]'::jsonb, '["Lima", "Lausanne", "Tokyo", "Los Angeles"]'::jsonb, 0, 'Sports', 'easy', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-c938253334ce7e5b', 'Which of these sports was added as an additional discipline for the Paris 2024 Games?', 'Lequel de ces sports a été ajouté comme discipline additionnelle pour les Jeux de Paris 2024 ?', '["Karate", "Squash", "Baseball", "Breakdance"]'::jsonb, '["Karaté", "Squash", "Baseball", "Breakdance"]'::jsonb, 3, 'Sports', 'medium', CURRENT_TIMESTAMP),
    (gen_random_uuid()::text, 'gen-098207e55ed349c7', 'Budapest withdrew its Olympic bid following a local referendum.', 'Budapest a retiré sa candidature olympique suite à un référendum local.', '["True", "False"]'::jsonb, '["Vrai", "Faux"]'::jsonb, 0, 'Sports', 'easy', CURRENT_TIMESTAMP)
ON CONFLICT DO NOTHING;

